if (desktopScene.matches && venues === venuesV3) {
    if (scrollPosition <= transitionStart) {
        assignOwner(false);
        return false;
    }
    // The basketball docks to a stable viewport coordinate just below
    // the header, instead of continuing upwards over it while the arena
    // scrolls. Coordinates stay relative to the existing foreground,
    // so its clipping/fade and the single sprite ownership are intact.
    const sliderRect = slider.getBoundingClientRect();
    const hostRect = ballHost.getBoundingClientRect();
    const dockX = sliderRect.left + sliderRect.width * activeProfile.to[0] / 1000;
    // Root coordinates are the ball centre. The visible sprite diameter
    // includes the atlas-cell visual-size correction from the CSS.
    // 13% of that diameter remains above the Hero's bottom edge at dock.
    const renderedDiameter = activeProfile.tileSize * activeProfile.endScale * 1.1327434;
    const dockY = sliderRect.bottom + renderedDiameter * (.5 - .13)
        + (scrollPosition - transitionStart);
    // Keep the single sprite visible beyond the clipped foreground:
    // a fixed child of the Page Builder is independent of section scroll.
    const fixedHost = scene.closest('.mskba-page-builder');
    if (fixedHost) {
        if (root.parentElement !== fixedHost) fixedHost.append(root);
        root.style.position = 'fixed';
        root.style.zIndex = '7';
        root.style.left = dockX.toFixed(2) + 'px';
        root.style.top = dockY.toFixed(2) + 'px';
    } else {
        assignOwner(true, ballHost);
        root.style.left = (dockX - hostRect.left).toFixed(2) + 'px';
        root.style.top = (dockY - hostRect.top).toFixed(2) + 'px';
    }
    root.style.setProperty('--ball-scale', activeProfile.endScale.toFixed(4));
    root.style.setProperty('--ball-brightness', '0.92');
    root.style.setProperty('--ball-saturation', '1');
    const elapsedTurns = rollingBallReducedMotion.matches ? 0
        : rollingBallTurns + Math.max(0, scrollPosition - transitionStart) / 320;
    const frame = Math.floor(elapsedTurns * rollingBallSpriteFrames) % rollingBallSpriteFrames;
    root.style.setProperty('--ball-frame-x', `${(frame % 4) * 100 / 3}%`);
    root.style.setProperty('--ball-frame-y', `${Math.floor(frame / 4) * 100 / 3}%`);
    return true;
}

