// Desktop: ball stays in the Hero's document coordinate system.
// Once at the terminal slider position, only atlas rotation changes
// with scroll. Never move the sprite to a viewport-fixed overlay.
if (desktopScene.matches && venues === venuesV3) {
    assignOwner(false);
    return false;
}
